def minDeletionSize(strs):
    n = len(strs)
    k = len(strs[0])
    dp = [1] * k  # dp[j]: max length of ordered subsequence ending at column j

    for j in range(k):
        for i in range(j):
            # Check if for all rows, col i ≤ col j
            if all(strs[row][i] <= strs[row][j] for row in range(n)):
                dp[j] = max(dp[j], dp[i] + 1)

    return k - max(dp)
